import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.wVcpyw2-.js";const o="/images/placeholder-payment-callback-config.svg",u=JSON.parse('{"title":"支付与提现","description":"支付与提现：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/payment.md","filePath":"features/payment.md","lastUpdated":1785020677000}'),l={name:"features/payment.md"};function n(i,a,p,h,d,g){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="支付与提现" tabindex="-1">支付与提现 <a class="header-anchor" href="#支付与提现" aria-label="Permalink to &quot;支付与提现&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">微信支付详细手册</p><p>微信商户平台逐步操作、后台逐字段、回调、提现打款、故障排查请参阅：</p><p>👉 <strong><a href="/features/wechat-pay">微信支付（完整配置手册）</a></strong></p></div><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>配置微信支付、支付宝收单，处理用户提现申请，并为红包、转账、商城等业务提供支付能力。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>站点使用 <strong>HTTPS 正式域名</strong>，且与 <strong>系统设置 → 网站信息</strong> 一致。</li><li>支付、提现相关能力已在授权中开通。</li><li>已在微信商户平台 / 支付宝开放平台完成企业资质与应用创建。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="_1-微信支付" tabindex="-1">1. 微信支付 <a class="header-anchor" href="#_1-微信支付" aria-label="Permalink to &quot;1. 微信支付&quot;">​</a></h3><p>详见 <strong><a href="/features/wechat-pay">微信支付（完整配置手册）</a></strong>。</p><p>路径：<strong>系统设置 → 系统配置 → 微信支付</strong> Tab</p><p>回调 URL：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/api/payment/wx-notify</span></span></code></pre></div><h3 id="_2-支付宝" tabindex="-1">2. 支付宝 <a class="header-anchor" href="#_2-支付宝" aria-label="Permalink to &quot;2. 支付宝&quot;">​</a></h3><p>路径：<strong>系统设置 → 系统配置 → 支付宝</strong> Tab</p><p>填写应用 AppID、应用私钥、支付宝公钥，并选择 <strong>生产</strong> 或 <strong>沙箱</strong> 环境。</p><p><strong>支付宝开放平台回调 URL：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/api/payment/alipay-notify</span></span></code></pre></div><p>在应用 <strong>网关设置</strong> 中配置上述地址。</p><h3 id="_3-虚拟支付-可选" tabindex="-1">3. 虚拟支付（可选） <a class="header-anchor" href="#_3-虚拟支付-可选" aria-label="Permalink to &quot;3. 虚拟支付（可选）&quot;">​</a></h3><p>路径：<strong>系统设置 → 系统配置</strong> 中 <strong>虚拟支付</strong> Tab（若可见）</p><p>仅微信小程序内虚拟代币场景；需在小程序后台开通虚拟支付，并与商品配置对齐。</p><h3 id="_4-提现处理" tabindex="-1">4. 提现处理 <a class="header-anchor" href="#_4-提现处理" aria-label="Permalink to &quot;4. 提现处理&quot;">​</a></h3><p>路径：<strong>财务管理 → 提现处理</strong></p><ul><li>查看用户提现申请列表</li><li>审核通过 / 拒绝</li><li>若已配置商户转账能力，系统可自动打款至微信零钱 / 支付宝</li></ul><p>提现规则（最小金额、手续费等）在提现设置与 <strong>区域列表</strong> 相关字段中维护（以页面为准）。</p><h3 id="_5-流水查询" tabindex="-1">5. 流水查询 <a class="header-anchor" href="#_5-流水查询" aria-label="Permalink to &quot;5. 流水查询&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>财务管理 → 资金交易</strong></td><td>支付、退款、转账流水</td></tr><tr><td><strong>财务管理 → 余额流水</strong></td><td>用户余额变动</td></tr><tr><td><strong>系统监控 → 对账中心</strong></td><td>异常订单对账（需权限）</td></tr></tbody></table><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>提现费率、区域是否允许提现等，可在 <strong>区域管理 → 区域列表</strong> 编辑区域时设置（字段以页面为准）。</p><p>支付渠道本身为 <strong>全站统一</strong> 配置，不按区域区分商户号。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>客户端发起一笔 <strong>0.01 元</strong> 测试支付（微信或支付宝），支付成功。</li><li><strong>财务管理 → 资金交易</strong> 出现对应成功记录。</li><li>提交一笔测试提现，在 <strong>提现处理</strong> 中审核并完成打款（或确认自动打款到账）。</li><li><strong>系统监控 → 系统状态</strong> 无持续「回调验签失败」类提示。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>支付页打不开或提示未配置</strong></p><ul><li>检查对应 Tab 必填项是否保存；授权是否含支付能力。</li><li>小程序 AppID 是否与商户号绑定。</li></ul><p><strong>已付款订单仍显示待支付</strong></p><ul><li>回调 URL 错误或外网不可达；证书 / 公钥与商户平台不一致。</li><li>联系运维确认反向代理未缓存 POST body。</li></ul><p><strong>提现打款失败</strong></p><ul><li>是否填写 <strong>转账场景 ID</strong> 并开通「商家转账到零钱」。</li><li>用户是否完成实名与收款账号绑定。</li><li>商户账户余额是否充足。</li></ul><p><strong>支付宝沙箱与生产混淆</strong></p><ul><li><strong>系统配置 → 支付宝</strong> 中「生产 / 沙箱」须与开放平台环境一致。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/wechat">微信（登录/支付）</a></li><li><a href="/features/message">私信与群聊</a>（红包 / 转账）</li><li><a href="/config/system-settings">系统配置总览</a></li></ul><p><img src="'+o+'" alt="支付回调配置示意"></p>',44)])])}const b=t(l,[["render",n]]);export{u as __pageData,b as default};
